import React, { useRef } from 'react';
import { buildPropsMap, createComponentDependency, 
//useImperativeProps,
toAttribute, useImperativeProps, useListeners, withNeonWebComponent } from './utils/react-utils';
import { buttonDependencies } from './neon-button';
export const layoutDetailDependencies = [
    createComponentDependency('layout-detail'),
    ...buttonDependencies
];
function LayoutDetail(props) {
    const elementRef = useRef();
    // * * * Set Props * * *
    useImperativeProps(elementRef, {
        preCloseCallback: props.preCloseCallback
    });
    // * * * Set Listeners * * *
    useListeners(elementRef, {
        neonLayoutDetailHasClosed: (event) => {
            props.neonLayoutDetailHasClosed();
        },
        neonLayoutDetailMobilePaneClose: (event) => {
            if (props.neonLayoutDetailMobilePaneClose) {
                props.neonLayoutDetailMobilePaneClose();
            }
        }
    });
    // * * * Set Attributes * * *
    return React.createElement('neon-2_20_1-layout-detail', buildPropsMap(props, {
        ref: elementRef,
        'data-animate': toAttribute(props.dataAnimate),
        'data-back-button-text': props.dataBackButtonText,
        //If someone turns off the spacing, they are responsible for using the spacing classes in the injected content
        //spacing classes: neon-2_20_1-layout-detail-body, neon-2_20_1-layout-detail-pre-body, and neon-2_20_1-layout-detail-post-body
        'data-injection-spacing': toAttribute(props.dataInjectionSpacing),
        //If someone turns off the body scroll, they are responsible for adding in neon-2_20_1-layout-scrollable on their own.
        //This should really only be used if someone needs to put a separate scrolling side-bar inside the detail panel.  (something like a wizard view)
        //The default behavior is true
        'data-body-scroll': toAttribute(props.dataBodyScroll),
        // When true the body and its wrappers will be full height. Developers will need to add neon-2_20_1-layout-scrollable or their own styles to sections that need to scroll.
        'data-body-full-height': toAttribute(props.dataBodyFullHeight),
        'data-show-header-divider': toAttribute(props.dataShowHeaderDivider),
        'data-show-pre-body-divider': toAttribute(props.dataShowPreBodyDivider),
        'data-show-post-body-divider': toAttribute(props.dataShowPostBodyDivider),
        'data-show-footer-divider': toAttribute(props.dataShowFooterDivider),
        // default is left
        'data-mobile-landing-pane': props.dataMobileLandingPane,
        'data-show-mobile-secondary-pane': toAttribute(props.dataShowMobileSecondaryPane),
        'data-bypass-focus-trap': toAttribute(props.dataBypassFocusTrap),
        // 'data-layout': props.dataLayout
    }), props.children);
}
export const NeonLayoutDetail = withNeonWebComponent('neon-2_20_1-layout-detail', LayoutDetail, layoutDetailDependencies);
